"""Author judgments of concrete omissions and fairness, not an automated grader."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
cases=[]
def case(goal, name, response, credits, cap, reason, expected_total, expected_pass):
    data=json.loads((HERE/goal/'proposed-whole-goal.draft.json').read_text())
    steps=data['examData']['scoring']['steps']
    assert len(credits)==len(steps)
    assert all(0<=credit<=step['points'] for step,credit in zip(steps,credits))
    raw=sum(credits);total=min(raw,14) if cap else raw
    assert total==expected_total and (total>=15)==expected_pass,(name,total)
    cases.append({'goalId':goal,'case':name,'actualCounterexampleOrResponseDescription':response,
      'authorStepCredits':[{'step':step['id'],'credit':credit,'max':step['points']} for step,credit in zip(steps,credits)],
      'authorJudgmentCapApplies':cap,'authorJudgmentReason':reason,'rawPoints':raw,'finalPoints':total,'binaryPass':total>=15,
      'limit':'This tests the author interpretation of the written rubric and score arithmetic. It does not execute a production grader or establish independent acceptance.'})
